window.createPlanningSystem = function(ctx) {
  const {files,arch,openapi,tasks,testRows,testLinks,esc,code}=ctx;
  const key='makora.plan.review.v2';
  const initial=()=>({steps:Array.from({length:5},()=>({status:'draft',note:''})),signatures:[],reviews:{},decisions:{},events:[]});
  let state;try{state=JSON.parse(localStorage.getItem(key))||initial()}catch{state=initial()}
  if(!Array.isArray(state.steps)||state.steps.length!==5)state=initial();
  state.signatures=state.signatures||[];state.reviews=state.reviews||{};state.decisions=state.decisions||{};state.events=state.events||[];
  const save=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{}};
  function hash(s){let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return (h>>>0).toString(16)}
  function auditArtifacts(){const sig=files.slice(0,4).map(f=>hash(f.content));let first=-1;sig.forEach((v,i)=>{if(state.signatures[i]&&state.signatures[i]!==v&&(first<0||i<first))first=i});if(first>=0){for(let i=first;i<5;i++){if(state.steps[i].status==='approved')state.steps[i].status='stale'}state.reviews={};state.decisions={};state.events.push({time:new Date().toISOString(),action:'Изменился исходный артефакт; зависимые шаги требуют перепроверки',step:first+1})}state.signatures=sig;save()}
  const timestamp=()=>new Date().toISOString();
  function result(name,ok,detail){return {name,status:ok?'passed':'error',detail}}
  function automatic(){
    const checks=[];let schema;try{schema=window.planOpenAPI(openapi)}catch(e){schema={ok:false,message:'Валидатор не загрузился: '+e.message}}checks.push(result('OpenAPI 3.0 и ссылки',!!schema.ok,schema.message));
    let data;try{data=JSON.parse(files[3].content);checks.push(result('JSON задач',Array.isArray(data.tasks),'JSON разобран; поле tasks должно быть массивом.'))}catch(e){checks.push(result('JSON задач',false,e.message));return checks}
    const list=Array.isArray(data.tasks)?data.tasks:[],ids=list.map(t=>t.id),unique=new Set(ids);
    checks.push(result('Идентификаторы задач',ids.length>0&&unique.size===ids.length&&ids.every(Boolean),`Всего ${ids.length}; уникальных ${unique.size}.`));
    const missing=list.flatMap(t=>(t.dependsOn||[]).filter(d=>!unique.has(d)).map(d=>`${t.id} → ${d}`));checks.push(result('Существование зависимостей',!missing.length,missing.length?missing.join(', '):'Все ссылки на задачи разрешены.'));
    let colors={},cycle=false;const byId=Object.fromEntries(list.map(t=>[t.id,t]));function visit(id){if(colors[id]===1){cycle=true;return}if(colors[id]===2)return;colors[id]=1;(byId[id]?.dependsOn||[]).forEach(d=>{if(byId[d])visit(d)});colors[id]=2}ids.forEach(visit);checks.push(result('Отсутствие циклов',!cycle,cycle?'Обнаружен цикл в зависимостях.':'Циклы в графе зависимостей не обнаружены.'));
    const testIds=new Set(testLinks.map(t=>t.id));const uncovered=list.filter(t=>!Array.isArray(t.tests)||!t.tests.length||t.tests.some(id=>!testIds.has(id))).map(t=>t.id);checks.push(result('Покрытие задач тестами',!uncovered.length,uncovered.length?'Нет проверок или неизвестный тест: '+uncovered.join(', '):`У каждой из ${list.length} задач указан существующий тест.`));
    const badLinks=testLinks.flatMap(t=>t.tasks.filter(id=>!unique.has(id)).map(id=>`${t.id} → ${id}`));checks.push(result('Связи тестов и задач',!badLinks.length,badLinks.length?badLinks.join(', '):'Все ссылки тестов на задачи существуют.'));
    const needed=['REQ-001','REQ-002','REQ-003','REQ-004','REQ-005'];const covered=new Set(testLinks.flatMap(t=>t.requirements));let missingReq=needed.filter(x=>!covered.has(x));checks.push(result('Покрытие требований тестами',!missingReq.length,missingReq.length?'Не покрыты: '+missingReq.join(', '):'Для REQ-001–REQ-005 указан минимум один сценарий.'));
    return checks;
  }
  function readiness(){const checks=automatic();const missing=[];if(checks.some(x=>x.status==='error'))missing.push('исправить ошибки автоматических проверок');if(state.steps.slice(0,4).some(x=>x.status!=='approved'))missing.push('утвердить первые четыре шага');if(!state.reviews.architecture||!state.reviews.tasks)missing.push('зафиксировать экспертную оценку');if(!state.decisions.rules)missing.push('согласовать правила статусов и стек');if(!state.decisions.demo)missing.push('подтвердить использование демо-данных');return {checks,missing,ready:!missing.length&&state.steps[4].status==='approved'}}
  const labels={draft:'Не утверждён',approved:'Утверждён',changes:'Запрошены изменения',stale:'Требует перепроверки'};
  const statusClass=s=>s==='approved'?'passed':s==='changes'||s==='stale'?'warning':'pending';
  function downloadText(name,text,type='text/markdown'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:type+';charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
  function taskBrief(t){const linked=testLinks.filter(x=>x.tasks.includes(t.id)).map(x=>{const i=testLinks.indexOf(x);return `- ${x.id} · ${testRows[i][1]}: ${testRows[i][2]} → ${testRows[i][3]} (требования: ${x.requirements.join(', ')})`}).join('\n');return `# Задание агенту: ${t.id} — ${t.title}\n\nПриоритет: ${t.priority} · Группа: ${t.group} · Оценка: ${t.estimate}\n\n## Состояние согласования\n${state.steps.slice(0,4).every(x=>x.status==='approved')?'Первые четыре шага утверждены.':'Черновик: первые четыре шага ещё не утверждены или требуют перепроверки.'}\n\n## Цель\n${t.goal}\n\n## Зависимости\n${t.dependsOn.length?t.dependsOn.join(', '):'Нет'}\n\n## Требования\n${t.requirements.join(', ')}\n\n## Контракты и материалы\n- 03_architecture.md\n- 03_contracts/openapi.yaml — модель Space\n- 03_test_plan.md\n\n## Собственные проверки задачи\n${linked}\n\n## Критерий готовности\n${t.acceptance}\n${t.completionRule}\n\n## Контекст архитектуры (копия)\n${arch}\n\n## Контракт OpenAPI (копия)\n\`\`\`yaml\n${openapi}\n\`\`\`\n\n> Учебный кейс: внешний источник занятости, правила статусов и стек требуют подтверждения.\n`}
  function taskDetail(t){return `<div class="agent-task-heading"><div><span class="plan-eyebrow">ЗАДАНИЕ ДЛЯ АГЕНТА · ${esc(t.priority)}</span><h3>${esc(t.id)} — ${esc(t.title)}</h3></div><button type="button" class="plan-secondary" id="download-agent-task">${state.steps.slice(0,4).every(x=>x.status==='approved')?'Скачать задание ↓':'Скачать черновик ↓'}</button></div><div class="agent-fields"><div><strong>Цель</strong><span>${esc(t.goal)}</span></div><div><strong>Зависимости</strong><span>${esc(t.dependsOn.join(', ')||'Нет')}</span></div><div><strong>Контракты</strong><span>Space · 03_contracts/openapi.yaml</span></div><div><strong>Требования</strong><span>${esc(t.requirements.join(', '))}</span></div><div><strong>Проверки</strong><span>${esc(t.tests.join(', '))}</span></div><div><strong>Критерий готовности</strong><span>${esc(t.acceptance)} ${esc(t.completionRule)}</span></div><div><strong>Контекст</strong><span>03_architecture.md · 03_test_plan.md · полный контракт включён в скачиваемое задание</span></div></div>`}
  function bindTask(t){document.querySelector('#download-agent-task').onclick=()=>downloadText(`${t.id}_agent_task.md`,taskBrief(t))}
  function stepActions(i){const current=state.steps[i];const note=current.note?`<div class="plan-feedback"><strong>Комментарий:</strong> ${esc(current.note)}</div>`:'';return `<div class="approval-panel"><div class="approval-heading"><div><span class="plan-eyebrow">СОГЛАСОВАНИЕ ШАГА ${String(i+1).padStart(2,'0')}</span><h3>${labels[current.status]}</h3></div><span class="review-pill ${statusClass(current.status)}">${labels[current.status]}</span></div>${note}<p>Утверждение сохраняется на этом устройстве. Запрос изменений пометит зависимые шаги для перепроверки.</p><div class="approval-buttons"><button type="button" class="plan-secondary" id="request-change">Запросить изменения</button><button type="button" class="plan-primary" id="approve-step">Утвердить шаг</button></div><div class="change-form" id="change-form" hidden><label for="change-note">Что нужно изменить?</label><textarea id="change-note" placeholder="Опишите необходимые изменения"></textarea><button class="plan-primary" id="save-change" type="button">Сохранить запрос</button></div><div id="approval-error" class="plan-error" role="status"></div></div>`}
  function autoHtml(checks){return checks.map(x=>`<div class="check-row"><span class="check-symbol ${x.status==='passed'?'ok':'warning'}">${x.status==='passed'?'✓':'!'}</span><div><strong>${esc(x.name)}</strong><p>${esc(x.detail)}</p></div><span class="check-label">${x.status==='passed'?'ПРОЙДЕНО':'ОШИБКА'}</span></div>`).join('')}
  function validationHtml(){const r=readiness(),allPassed=!r.missing.length;return `<div class="plan-eyebrow">ГОТОВНОСТЬ К РАЗРАБОТКЕ</div><div class="validation-summary"><span class="validation-icon">${r.ready?'✓':'◐'}</span><div><strong>${r.ready?'Готово к подготовке мок-данных':'План требует уточнений'}</strong><p>${r.ready?'Все условия и согласование зафиксированы.':allPassed?'Все проверки и решения зафиксированы. Утвердите валидацию.':esc(r.missing.join(' · '))}</p></div></div><div class="checks-section"><div class="approval-heading"><div><span class="plan-eyebrow">01 / АВТОМАТИЧЕСКИ</span><h3>Проверки артефактов</h3></div><button type="button" class="plan-secondary" id="run-validation">Повторить проверки ↻</button></div><p>Проверяются текущие содержимое OpenAPI и JSON, ссылки и граф; код будущего продукта не запускается.</p>${autoHtml(r.checks)}</div><div class="checks-section"><span class="plan-eyebrow">02 / ЭКСПЕРТНАЯ ОЦЕНКА</span><h3>Проверка смысловой полноты</h3><p>Агент в этом макете не подключён. Человек может отдельно зафиксировать ручную экспертную проверку.</p>${[['architecture','Архитектура соответствует требованиям'],['tasks','Декомпозиция полна и риски учтены']].map(([id,title])=>`<div class="check-row"><span class="check-symbol ${state.reviews[id]?'ok':'pending'}">${state.reviews[id]?'✓':'○'}</span><div><strong>${title}</strong><p>${state.reviews[id]?'Проверено человеком · '+esc(state.reviews[id]):'Агентом не проверялось; ручная проверка не подтверждена.'}</p></div><button class="plan-secondary small" type="button" data-review="${id}">${state.reviews[id]?'Отменить':'Подтвердить вручную'}</button></div>`).join('')}</div><div class="checks-section"><span class="plan-eyebrow">03 / РЕШЕНИЯ ЧЕЛОВЕКА</span><h3>Открытые решения</h3><div class="decision-card"><strong>Источник актуальной занятости не подтверждён</strong><p>Продолжать с мок-данными можно только как с демонстрационным источником; это не подтверждает наличие реального API.</p><label for="risk-note">Условия принятия риска</label><textarea id="risk-note" placeholder="Например: использовать только для демо; источник помечать как demo">${esc(state.decisions.demo?.note||'')}</textarea><button type="button" class="plan-secondary" id="accept-demo">${state.decisions.demo?'Обновить решение':'Принять риск и использовать демо-данные'}</button>${state.decisions.demo?`<p>Решение зафиксировано: ${esc(state.decisions.demo.note)} · ${esc(state.decisions.demo.time)}</p>`:''}</div><div class="decision-card"><strong>Пороги статусов и выбранный стек не подтверждены</strong><p>Запишите рабочее решение или причину, по которой допустимо перейти к подготовке фикстур до согласования.</p><label for="rules-note">Решение</label><textarea id="rules-note" placeholder="Например: пороги уточнить до реализации; для макета использовать тестовые значения">${esc(state.decisions.rules?.note||'')}</textarea><button type="button" class="plan-secondary" id="accept-rules">${state.decisions.rules?'Обновить решение':'Зафиксировать решение'}</button>${state.decisions.rules?`<p>Решение зафиксировано: ${esc(state.decisions.rules.note)} · ${esc(state.decisions.rules.time)}</p>`:''}</div></div>${r.ready?'<button type="button" class="plan-primary mock-action" id="prepare-mocks">Перейти к подготовке мок-данных →</button>':''}<div id="validation-action-status" class="plan-error" role="status"></div>`}
  function saveReview(id){if(state.reviews[id])delete state.reviews[id];else state.reviews[id]=timestamp();if(state.steps[4].status==='approved')state.steps[4].status='stale';save()}
  function invalidate(start){for(let n=start;n<5;n++)if(state.steps[n].status==='approved')state.steps[n].status='stale';if(start<4){state.reviews={};state.decisions={}}}
  function mount(i,rerender){auditArtifacts();let el=document.querySelector('#planning-controls');if(!el)return;let supplementary='';if(i===0)supplementary='<div class="decision-strip"><strong>Не подтверждено</strong><span>Источник занятости · пороги статусов · стек API</span></div>';if(i===1){const check=automatic()[0];supplementary=`<div class="contract-result ${check.status}"><strong>${check.status==='passed'?'✓ Схема проверена':'! Ошибка схемы'}</strong><p>${esc(check.detail)}</p><span>Проверка структуры OpenAPI 3.0 и локальных ссылок; реализация API не проверялась.</span></div>`}if(i===4)supplementary=validationHtml();el.innerHTML=supplementary+stepActions(i);
    el.querySelector('#request-change').onclick=()=>{el.querySelector('#change-form').hidden=false;el.querySelector('#change-note').focus()};
    el.querySelector('#save-change').onclick=()=>{let text=el.querySelector('#change-note').value.trim();if(!text){el.querySelector('#approval-error').textContent='Опишите, какие изменения нужны.';return}state.steps[i]={status:'changes',note:text};invalidate(i+1);if(i<4)state.reviews={};state.events.push({time:timestamp(),step:i+1,action:'Запрошены изменения',note:text});save();rerender(i)};
    el.querySelector('#approve-step').onclick=()=>{if(state.steps.slice(0,i).some(x=>x.status!=='approved')){el.querySelector('#approval-error').textContent='Сначала утвердите предыдущие шаги.';return}if(i===1&&automatic().some(x=>x.name==='OpenAPI 3.0 и ссылки'&&x.status==='error')){el.querySelector('#approval-error').textContent='Сначала исправьте ошибки OpenAPI.';return}if(i===4&&readiness().missing.length){el.querySelector('#approval-error').textContent='Перед утверждением устраните ошибки и зафиксируйте проверки и решения выше.';return}state.steps[i]={status:'approved',note:state.steps[i].note,approvedAt:timestamp()};state.events.push({time:timestamp(),step:i+1,action:'Шаг утверждён'});save();rerender(i)};
    if(i!==4)return;
    el.querySelector('#run-validation').onclick=()=>rerender(4);
    el.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{saveReview(b.dataset.review);rerender(4)});
    for(const [id,field,button] of [['demo','risk-note','accept-demo'],['rules','rules-note','accept-rules']])el.querySelector('#'+button).onclick=()=>{const note=el.querySelector('#'+field).value.trim();if(!note){el.querySelector('#validation-action-status').textContent='Опишите решение и условия его применения.';return}state.decisions[id]={note,time:timestamp()};if(state.steps[4].status==='approved')state.steps[4].status='stale';state.events.push({time:timestamp(),action:id==='demo'?'Принят риск использования демо-данных':'Зафиксировано техническое допущение',note});save();rerender(4)};
    const mock=el.querySelector('#prepare-mocks');if(mock)mock.onclick=()=>{auditArtifacts();if(!readiness().ready){rerender(4);return}if(window.openMockStage)window.openMockStage();else el.querySelector('#validation-action-status').textContent='Этап подготовки мок-данных недоступен.'};
  }
  function fileContent(i){if(i!==4)return files[i].content;const r=readiness();return '# Отчёт валидации плана\n\n## Готовность\n\n'+(r.ready?'Готово к подготовке мок-данных':'План требует уточнений: '+r.missing.join('; '))+'\n\n## Автоматические проверки\n\n'+r.checks.map(x=>`- ${x.status.toUpperCase()} — ${x.name}: ${x.detail}`).join('\n')+'\n\n## Экспертные проверки\n\n'+['architecture','tasks'].map(id=>`- ${id}: ${state.reviews[id]?'подтверждено человеком '+state.reviews[id]:'агентом и человеком не проверено'}`).join('\n')+'\n\n## Решения человека\n\n'+['demo','rules'].map(id=>`- ${id}: ${state.decisions[id]?state.decisions[id].note+' ('+state.decisions[id].time+')':'не подтверждено'}`).join('\n')+'\n\n## Согласование\n\n'+state.steps.map((s,i)=>`- Шаг ${i+1}: ${labels[s.status]}${s.note?' — '+s.note:''}`).join('\n')+'\n\n> Источник реальной занятости не подтверждён; подготовка демо-данных не подтверждает его наличие.\n'}
  auditArtifacts();return {mount,taskDetail,bindTask,fileContent,status:i=>labels[state.steps[i].status],getReadiness:()=>{auditArtifacts();return readiness()},getState:()=>JSON.parse(JSON.stringify(state))};
};
